<?php require_once '../includes/auth.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($id!==$_SESSION['user_id']&&in_array($action,['active','suspended'],true)){$q=$pdo->prepare("UPDATE users SET account_status=? WHERE id=? AND role='seller'");$q->execute([$action,$id]);audit_log('seller_'.$action,'user',$id,null);}}$q=$pdo->query("SELECT id,name,email,account_status,created_at FROM users WHERE role='seller' ORDER BY created_at DESC');$us=$q->fetchAll();$title='Seller management';require '../includes/header.php';?><h1>Seller management</h1><?php foreach($us as $u):?><div class="card mb-3"><div class="card-body"><strong><?=e($u['name'])?></strong><div><?=e($u['email'])?></div><div class="small text-muted">Joined <?=e($u['created_at'])?></div><span class="badge <?= $u['account_status']==='active'?'bg-success':'bg-danger'?>"><?=e($u['account_status'])?></span><form method="post" class="mt-2"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($u['id'])?>"><?php if($u['account_status']==='active'):?><button class="btn btn-outline-danger" name="action" value="suspended">Suspend seller</button><?php else:?><button class="btn btn-success" name="action" value="active">Activate seller</button><?php endif;?></form></div></div><?php endforeach;?><?php require '../includes/footer.php';?>